from main import solve

def same(actual, expected, path="result"):
    if isinstance(expected, torch.Tensor):
        assert isinstance(actual, torch.Tensor), f"{path}: return a tensor"
        assert actual.shape == expected.shape, f"{path}: expected shape {tuple(expected.shape)}, got {tuple(actual.shape)}"
        torch.testing.assert_close(actual, expected, rtol=1e-4, atol=1e-5, msg=lambda m: path+": "+m)
    elif isinstance(expected, dict):
        assert isinstance(actual, dict) and actual.keys() == expected.keys(), f"{path}: wrong keys"
        for k in expected: same(actual[k],expected[k],path+"."+str(k))
    elif isinstance(expected, (list,tuple)):
        assert isinstance(actual,(list,tuple)) and len(actual)==len(expected), f"{path}: wrong sequence length"
        for i,(a,b) in enumerate(zip(actual,expected)): same(a,b,path+"["+str(i)+"]")
    elif isinstance(expected,float):
        assert isinstance(actual,(int,float)) and math.isclose(actual,expected,rel_tol=1e-4,abs_tol=1e-5), f"{path}: expected {expected}, got {actual}"
    else:
        assert actual == expected, f"{path}: expected {expected!r}, got {actual!r}"

