import torch
from torch import nn

def solve(base, head):
    for p in base.parameters():
        p.requires_grad_(False)
    for p in head.parameters():
        p.requires_grad_(True)
    return sum(p.numel() for p in base.parameters() if p.requires_grad), sum(p.numel() for p in head.parameters() if p.requires_grad)

